_gunbc_stage="$(mktemp -d)"
trap 'rm -rf "$_gunbc_stage"' EXIT
cat > "$_gunbc_stage/gunbc-deploy.sudoers" <<'GUNBC_SUDOERS_EOF'
# GENERATED by dag/gunbc/ci_deploy_sudoers.dag — do not hand-edit
ghrunner ALL=(ALL) NOPASSWD: /usr/bin/apt-get
